<script setup>
import {wbListingPrice} from '../../../../src/shared/wb-listing-prices.js';
import {wbAttributeLabel} from '../../../../src/shared/wb-display.js';
import {computed,nextTick,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import WbBrandInput from './WbBrandInput.vue';
import WbAttributeInput from './WbAttributeInput.vue';
import WbListingVariantEditor from './WbListingVariantEditor.vue';
import {wbListingVariants,wbNewVariant,wbGeneratedVendorCode} from '../../../../src/shared/wb-listing-variants.js';
const props=defineProps({shopId:{type:Number,default:null},shops:{type:Array,default:()=>[]},schema:{type:Object,required:true},templates:{type:Array,default:()=>[]},draft:{type:Object,default:null},card:{type:Object,default:null}}),emit=defineEmits(['saved','shop-changed','upload-state']);
const clone=v=>JSON.parse(JSON.stringify(v)),initial=props.draft?.payload||{card:props.card||{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},characteristics:clone(props.schema.defaults?.characteristics||[]),sizes:[{techSize:'0',price:null,skus:[]}]},images:(props.card?.photos||[]).map(p=>p.big).filter(Boolean)};
const rows=ref(wbListingVariants(initial).map(clone)),shop=ref(props.draft?.target_shop_id||props.draft?.shop_id||props.shopId||null),savedShop=ref(props.draft?.shop_id||props.shopId||null),draftId=ref(props.draft?.id||null),revision=ref(props.draft?.revision||1),strategy=ref(initial.strategy||'grouped'),busy=ref(false),uploading=ref(0),active=ref(null),details=ref(null),preview=ref(false),errors=ref([]),source=reactive({query:'',rows:[]});
const selectedRows=ref([]),variantTable=ref(null);
const attributes=computed(()=>props.schema.attributes.filter(a=>!a.existNamedField&&Number(a.charcType)!==0).sort((a,b)=>Number(Boolean(b.required))-Number(Boolean(a.required))||Number(Boolean(b.isVariable))-Number(Boolean(a.isVariable))));
const editorMode=ref('images'),dialogTitle=computed(()=>({images:'编辑商品图片',video:'编辑商品视频',sizes:'编辑尺码与条码',package:'编辑包装尺寸与重量'}[editorMode.value]));
const appliedPolicy=ref(clone(initial.price_strategy||{sale_multiplier:1,old_multiplier:2,basis:'existing_sale'}));
const pricing=reactive({visible:false,saleMultiplier:Number(appliedPolicy.value.sale_multiplier)||1,oldMultiplier:Number(appliedPolicy.value.old_multiplier)||2,bases:[]});
const pricePreview=computed(()=>pricing.bases.map(item=>{try{return {...item,...wbListingPrice(item.base_price,pricing.saleMultiplier,pricing.oldMultiplier)};}catch(e){return {...item,error:e.message};}}));
function openPricing(index=null){pricing.saleMultiplier=Number(appliedPolicy.value.sale_multiplier)||1;pricing.oldMultiplier=Number(appliedPolicy.value.old_multiplier)||2;pricing.bases=[];for(const [rowIndex,row] of rows.value.entries())if(index===null||rowIndex===index)for(const [sizeIndex,size] of row.card.sizes.entries())pricing.bases.push({rowIndex,sizeIndex,base_price:size.price});pricing.visible=true;}
function applyPricing(){if(pricePreview.value.some(item=>item.error||!item.exact))return ElMessage.warning('请核对倍率、售价及 WB 整数折扣后的价格。');for(const item of pricePreview.value){const size=rows.value[item.rowIndex].card.sizes[item.sizeIndex];size.price=item.sale_price;size.old_price=item.old_price;size.pricing_base=item.base_price;}appliedPolicy.value={sale_multiplier:pricing.saleMultiplier,old_multiplier:pricing.oldMultiplier,basis:'existing_sale'};pricing.visible=false;}
function flush(){if(active.value!==null&&details.value)rows.value[active.value]=details.value.getPayload();}
function payload(){flush();const variants=clone(rows.value);return {...clone(initial),currency:'CNY',strategy:strategy.value,price_strategy:clone(appliedPolicy.value),template_id:Number(props.schema.template_id),subject_id:Number(props.schema.subject_id),variants,card:variants[0]?.card||{},images:variants[0]?.images||[],video_url:variants[0]?.video_url||''};}
function generate(row,index){if(row.card.nmID||draftId.value&&index===0)return;row.card.vendorCode=wbGeneratedVendorCode({brand:row.card.brand,subjectId:props.schema.subject_id,shopId:shop.value,index,random:crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase()});}
function generateAll(){rows.value.forEach((row,index)=>{if(!row.card.vendorCode)generate(row,index);});}
function addVariant(){if(rows.value.length>=30)return;const row=wbNewVariant(rows.value[0]);row.card.characteristics=clone((rows.value[0].card.characteristics||[]).filter(c=>props.schema.attributes.find(a=>Number(a.charcID)===Number(c.id))?.isVariable!==true));generate(row,rows.value.length);rows.value.push(row);}
async function edit(index,mode='images'){if(uploading.value)return;flush();active.value=null;editorMode.value=mode;await nextTick();active.value=index;}
function closeDetails(done){if(uploading.value)return;flush();active.value=null;if(typeof done==='function')done();}
function sameFirst(key){for(const row of rows.value.slice(1))row.card[key]=clone(rows.value[0].card[key]);}
function copyImages(){for(const row of rows.value.slice(1))row.images=clone(rows.value[0].images);}
function copyVideos(){for(const row of rows.value.slice(1)){row.video_url=rows.value[0].video_url||'';row.video_source_image=rows.value[0].video_source_image||'';}}
function copyPrices(){for(const row of rows.value.slice(1))for(const size of row.card.sizes)size.price=rows.value[0].card.sizes[0].price;}
async function generateVideo(index){if(uploading.value||busy.value)return;await edit(index,'video');await nextTick();await details.value?.generateVideo();flush();}
function removeSelected(){const selected=new Set(selectedRows.value);rows.value=rows.value.filter((row,index)=>index===0||!selected.has(row));selectedRows.value=[];variantTable.value?.clearSelection();}
function remove(index){if(rows.value.length===1||draftId.value&&index===0)return;rows.value.splice(index,1);}
async function run(work){if(busy.value||uploading.value)return;busy.value=true;const scope=currentApiCacheScope();try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
async function findSource(){await run(async scope=>{const r=await apiClient.get(`/api/listing/drafts?paged=1&lightweight=1&pageSize=20&query=${encodeURIComponent(source.query)}`,{noCache:true});if(scope===currentApiCacheScope())source.rows=r.rows||[];});}
async function importSource(id){await run(async scope=>{const r=await apiClient.get(`/api/wb/listing-source?source_draft_id=${id}${shop.value?`&shop_id=${shop.value}`:''}`,{noCache:true});if(scope!==currentApiCacheScope())return;rows.value=wbListingVariants(r).map(clone);source.rows=[];generateAll();});}
async function save(){if(!shop.value)throw Error('上架店铺：请在顶部选择目标 WB 店铺，再保存草稿。');generateAll();let saveId=draftId.value;if(saveId&&Number(savedShop.value)!==Number(shop.value)){await ElMessageBox.confirm('将保存为目标店铺的新草稿，原店铺草稿保留。','保存新店铺草稿');saveId=null;}const r=await apiClient.post('/api/wb/listing-drafts/save',{shop_id:shop.value,draft_id:saveId,revision:revision.value,payload:payload()});draftId.value=r.draft_id;revision.value=r.revision;savedShop.value=shop.value;emit('saved');}
async function saveOnly(){await run(async()=>{await save();ElMessage.success('WB 草稿已保存，未提交上架');});}
async function validate(){preview.value=true;errors.value=[];await run(async scope=>{const r=await apiClient.post('/api/wb/listing-preview',{shop_id:shop.value,payload:payload()});if(scope===currentApiCacheScope())errors.value=r.errors||[];});}
function uploadingChanged(value){uploading.value=value;emit('upload-state',value);}
function attributeValue(row,attribute){return row.card.characteristics?.find(v=>Number(v.id)===Number(attribute.charcID))?.value;}
function updateAttribute(row,attribute,value){row.card.characteristics=(row.card.characteristics||[]).filter(v=>Number(v.id)!==Number(attribute.charcID));row.card.characteristics.push({id:attribute.charcID,value:Number(attribute.charcType)===4?value:Array.isArray(value)?value:String(value||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)});}
function sameAttribute(attribute){const value=attributeValue(rows.value[0],attribute);for(const row of rows.value.slice(1))updateAttribute(row,attribute,value===undefined?'':clone(value));}
defineExpose({getPayload:payload,getShopId:()=>shop.value,getContext:()=>({id:draftId.value,revision:revision.value,shop_id:savedShop.value,target_shop_id:shop.value,payload:payload()}),saveDraft:saveOnly,preview:validate,reviewSubmission:validate});
</script>
<template>
 <div class="wb-workbench-fields">
  <section class="editor-block primary-information"><h3>主要信息</h3><el-form label-width="116px" class="workbench-settings" :disabled="busy||uploading>0"><el-form-item label="上架店铺" required><el-select v-model="shop" placeholder="选择 WB 店铺" clearable @change="id=>{if(id&&shops.find(s=>Number(s.id)===Number(id))?.environment!==schema.environment)emit('shop-changed');}"><el-option v-for="s in shops" :key="s.id" :value="Number(s.id)" :label="s.name"/></el-select></el-form-item><el-form-item label="商品组合"><div class="product-grouping"><el-radio-group v-model="strategy"><el-radio value="grouped">合并为一个商品</el-radio><el-radio value="independent">分别作为独立商品</el-radio></el-radio-group><p class="grouping-help">{{strategy==='grouped'?'例如：同款的不同颜色，作为一个商品的多个变体。':'每行分别建立商品，各自保留图片、属性和尺码。'}}</p></div></el-form-item><el-form-item label="产品类目" required><slot name="category"/></el-form-item></el-form></section>
  <section v-if="!draftId" class="editor-block source-bar"><el-input v-model="source.query" placeholder="引用已有草稿：输入货号或名称" @keyup.enter="findSource"/><el-button :loading="busy" @click="findSource">搜索草稿</el-button><el-table v-if="source.rows.length" :data="source.rows"><el-table-column prop="internal_code" label="货号"/><el-table-column prop="product_name" label="商品"/><el-table-column width="80"><template #default="{row}"><el-button link @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table></section>
  <section class="editor-block variants-block"><div class="section-line"><h3>WB 商品表格</h3><div class="variant-actions"><el-button type="primary" :disabled="rows.length>=30||busy||uploading>0" @click="addVariant">＋ 添加变体</el-button><el-button :disabled="busy||uploading>0" @click="generateAll">一键生成货号</el-button><el-button :disabled="busy||uploading>0" @click="openPricing()">定价策略</el-button><el-dropdown trigger="click" :disabled="busy||uploading>0"><el-button>批量操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="copyImages">图片同首行</el-dropdown-item><el-dropdown-item @click="copyVideos">视频同首行</el-dropdown-item><el-dropdown-item @click="sameFirst('title')">标题同首行</el-dropdown-item><el-dropdown-item @click="sameFirst('description')">描述同首行</el-dropdown-item><el-dropdown-item @click="copyPrices">售价同首行</el-dropdown-item><el-dropdown-item divided :disabled="!selectedRows.length" @click="removeSelected">删除选中变体（保留首行）</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div>
   <el-table ref="variantTable" :data="rows" :max-height="640" border stripe class="variant-table dense-variant-table" :scrollbar-always-on="true" @selection-change="selectedRows=$event">
    <el-table-column type="selection" width="46" fixed="left"/>
    <el-table-column type="index" label="序号" width="64" fixed="left" align="center"/>
    <el-table-column label="商品信息" fixed="left">
     <el-table-column width="210" fixed="left"><template #header><div class="variant-col-header"><span><em>*</em> 货号 / vendorCode</span><el-button link size="small" @click="generateAll">一键生成</el-button></div></template><template #default="{row,$index}"><div class="offer-id-cell"><el-input v-model="row.card.vendorCode" size="small" :disabled="!!row.card.nmID||!!draftId&&$index===0" maxlength="72"/><el-button size="small" :disabled="!!row.card.nmID||!!draftId&&$index===0" @click="generate(row,$index)">生成</el-button></div></template></el-table-column>
     <el-table-column width="260"><template #header><div class="variant-col-header"><span><em>*</em> SKU 名称 / 标题</span><el-button link size="small" @click="sameFirst('title')">同首行</el-button></div></template><template #default="{row}"><el-input v-model="row.card.title" type="textarea" :rows="3" maxlength="60" show-word-limit/></template></el-table-column>
     <el-table-column width="150"><template #header><div class="variant-col-header"><span>品牌</span><el-button link size="small" @click="sameFirst('brand')">同首行</el-button></div></template><template #default="{row}"><WbBrandInput v-model="row.card.brand" :subject-id="Number(schema.subject_id)" :shop-id="shop"/></template></el-table-column>
    </el-table-column>
    <el-table-column label="媒体">
     <el-table-column width="150"><template #header><div class="variant-col-header"><span><em>*</em> 图片</span><el-button link size="small" @click="copyImages">同首行</el-button></div></template><template #default="{row,$index}"><el-image v-if="row.images.length" :src="row.images[0]" :preview-src-list="row.images" preview-teleported fit="cover" class="row-image"/><div v-else class="row-image empty-image">无图</div><el-button link type="primary" @click="edit($index)">编辑图片（{{row.images.length}}）</el-button></template></el-table-column>
     <el-table-column width="190"><template #header><div class="variant-col-header"><span>视频</span><el-button link size="small" @click="copyVideos">同首行</el-button></div></template><template #default="{row,$index}"><video v-if="row.video_url" :src="row.video_url" controls preload="none" class="row-video"/><div v-else class="empty-video">暂无视频</div><div class="media-cell-actions"><el-button link type="primary" :disabled="!row.images.length||uploading>0" @click="generateVideo($index)">一键生成</el-button><el-button link type="primary" @click="edit($index,'video')">上传 / 编辑</el-button></div></template></el-table-column>
    </el-table-column>
    <el-table-column label="规格与价格">
     <el-table-column label="尺码 / 条码" width="160"><template #default="{row,$index}"><span>{{row.card.sizes.length}} 个尺码</span><div><el-button link type="primary" @click="edit($index,'sizes')">编辑尺码与条码</el-button></div></template></el-table-column>
     <el-table-column width="160"><template #header><div class="variant-col-header"><span>售价（CNY）</span><el-button link size="small" @click="copyPrices">同首行</el-button></div></template><template #default="{row}"><el-input-number v-model="row.card.sizes[0].price" :min="1" :precision="0" :controls="false"/><el-button v-if="row.card.sizes.length>1" link @click="edit(rows.indexOf(row),'sizes')">编辑各尺码售价</el-button></template></el-table-column>
     <el-table-column width="170"><template #header><div class="variant-col-header"><span>划线价（CNY）</span><el-button link size="small" @click="openPricing()">倍率设置</el-button></div></template><template #default="{row,$index}"><el-input-number v-model="row.card.sizes[0].old_price" :min="1" :precision="0" :controls="false"/><el-button link type="primary" @click="openPricing($index)">定价策略</el-button></template></el-table-column>
    </el-table-column>
    <el-table-column label="包装"><el-table-column width="190"><template #header><div class="variant-col-header"><span>尺寸 / 重量</span><el-button link size="small" @click="sameFirst('dimensions')">同首行</el-button></div></template><template #default="{row,$index}"><div>{{row.card.dimensions.length||'—'}} × {{row.card.dimensions.width||'—'}} × {{row.card.dimensions.height||'—'}} cm</div><div>{{row.card.dimensions.weightBrutto??'—'}} kg</div><el-button link type="primary" @click="edit($index,'package')">编辑包装</el-button></template></el-table-column></el-table-column>
    <el-table-column label="内容"><el-table-column width="280"><template #header><div class="variant-col-header"><span>简介 / 描述</span><el-button link size="small" @click="sameFirst('description')">同首行</el-button></div></template><template #default="{row}"><el-input v-model="row.card.description" type="textarea" :rows="3"/></template></el-table-column></el-table-column>
    <el-table-column v-for="attribute in attributes" :key="attribute.charcID" width="210"><template #header><div class="variant-col-header"><span><em v-if="attribute.required">*</em> {{wbAttributeLabel(attribute)}}</span><el-button link size="small" @click="sameAttribute(attribute)">同首行</el-button></div></template><template #default="{row}"><WbAttributeInput :model-value="attributeValue(row,attribute)" :attribute="attribute" :subject-id="Number(schema.subject_id)" :shop-id="shop" @update:model-value="updateAttribute(row,attribute,$event)"/></template></el-table-column>
    <el-table-column label="操作" width="110" fixed="right"><template #default="{$index}"><el-button link type="danger" :disabled="rows.length===1||!!draftId&&$index===0" @click="remove($index)">删除</el-button></template></el-table-column>
   </el-table>
  </section>
  <el-dialog v-if="active!==null" :model-value="true" :title="dialogTitle+' · 变体 '+(active+1)" width="min(1000px,96vw)" :before-close="closeDetails" :close-on-click-modal="false"><WbListingVariantEditor :key="active+':'+editorMode" ref="details" :mode="editorMode" :shop-id="shop" :shops="shops" :schema="schema" :templates="templates" :draft="{id:active===0?draftId:null,payload:rows[active],shop_id:shop}" @upload-state="uploadingChanged"/><template #footer><el-button type="primary" :disabled="uploading>0" @click="closeDetails">完成编辑</el-button></template></el-dialog>
  <el-dialog v-if="pricing.visible" v-model="pricing.visible" title="售价与划线价策略" width="min(900px,95vw)"><el-alert title="以当前已有售价为基数；售价和划线价分别乘以各自倍率。仅修改本地草稿。" :closable="false"/><el-form inline style="margin-top:16px"><el-form-item label="售价倍率"><el-input-number v-model="pricing.saleMultiplier" :min="0.01" :precision="2"/></el-form-item><el-form-item label="划线价倍率"><el-input-number v-model="pricing.oldMultiplier" :min="0.01" :precision="2"/></el-form-item></el-form><el-table :data="pricePreview" border><el-table-column label="变体 / 尺码"><template #default="{row}">{{row.rowIndex+1}} / {{row.sizeIndex+1}}</template></el-table-column><el-table-column prop="base_price" label="已有售价"/><el-table-column prop="sale_price" label="新售价"/><el-table-column prop="old_price" label="划线价"/><el-table-column label="WB 卖家折扣"><template #default="{row}">{{row.discount===undefined?'—':row.discount+'%'}}</template></el-table-column><el-table-column label="校验"><template #default="{row}">{{row.error||(!row.exact?'整数折扣后为 '+row.effective_price+' 元，请调整倍率':'可应用')}}</template></el-table-column></el-table><template #footer><el-button @click="pricing.visible=false">取消</el-button><el-button type="primary" @click="applyPricing">应用到草稿</el-button></template></el-dialog>
  <el-drawer v-if="preview" :model-value="true" title="WB 商品预览与校验" size="min(900px,95vw)" @close="preview=false"><el-alert title="仅校验草稿，尚未提交 WB" :closable="false"/><section v-for="(row,index) in rows" :key="index"><h3>{{index+1}}. {{row.card.title||'待填写标题'}}</h3><p>{{row.card.vendorCode}} · {{row.card.sizes.map(s=>'¥ '+(s.price??'待填写')).join(' / ')}} CNY</p><el-image v-for="(image,i) in row.images" :key="image" :src="image" :preview-src-list="row.images" :initial-index="i" preview-teleported fit="cover" class="preview-image"/><video v-if="row.video_url" :src="row.video_url" controls class="preview-video"/></section><el-alert v-for="error in errors" :key="error" :title="error" type="warning" :closable="false"/><el-button type="primary" :loading="busy" @click="saveOnly">保存草稿</el-button></el-drawer>
 </div>
</template>
<style scoped>
.wb-workbench-fields{display:flex;flex-direction:column;gap:16px}.editor-block{padding:24px 0;border:0;border-radius:0;background:var(--erp-detail-surface,var(--el-bg-color))}.workbench-settings{max-width:760px;margin:0 auto}.workbench-settings :deep(.el-form-item){margin-bottom:18px!important}.workbench-settings :deep(.el-select){width:100%!important}.workbench-settings :deep(.el-form-item){margin-bottom:0}.workbench-settings :deep(.el-select){width:240px}.section-line{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.editor-block h3{margin:0 0 22px;font-size:18px;text-align:center}.section-line{position:relative;min-height:40px;justify-content:center;margin-bottom:22px}.section-line h3{margin:0}.variant-actions{position:absolute;right:0;display:flex;gap:8px}.source-bar{display:flex;gap:8px;flex-wrap:wrap}.source-bar>.el-input{max-width:380px}.row-image{width:64px;height:84px;display:block;border-radius:4px}.empty-image{display:flex;align-items:center;justify-content:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary)}.variant-table :deep(.el-table__header th){background:var(--el-fill-color-light);font-weight:600}.variant-table :deep(.el-table__cell){padding:8px}.variant-table :deep(.el-input-number){width:100%}.common-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.common-grid :deep(.el-form-item__label){height:auto;line-height:20px;min-height:32px;align-items:center;overflow-wrap:anywhere}.common-grid :deep(.el-select){width:100%}.preview-image{width:96px;height:126px;margin:4px}.preview-video{display:block;max-width:100%;max-height:280px}@media(max-width:1100px){.common-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.section-line{flex-wrap:wrap}}@media(max-width:700px){.common-grid{grid-template-columns:1fr}}
